// ==UserScript==
// @name        Multidonate Dwarf Mod
// @namespace   http://tampermonkey.net/
// @version     156.0
// @match       https://play.multidonate.ru/*
// @run-at      document-start
// @grant       none
// ==/UserScript==

(function() {
    'use strict';

    // ==========================================
    // ЧАСТЬ 1: КОНФИГУРАЦИЯ (ВСТАВЛЯЙ ССЫЛКИ И BASE64)
    // ==========================================

    // 1. Спрайты для КЛАССОВ (используются, если у игрока нет кастомного спрайта)
    const CLASS_SPRITES = {
        legionary:   "data:image/png;base64,",
        archer:      "data:image/png;base64,",
        mage:        "data:image/png;base64,",
        priest:      "data:image/png;base64,",
        rogue:       "data:image/png;base64,",
        necromancer: "data:image/png;base64,",
        paladin:     "data:image/png;base64,",
        recruit:     "data:image/png;base64,"
    };

    // 2. Спрайты для КОНКРЕТНЫХ ИГРОКОВ (по нику)
    // Формат: 'НикВИгре': 'ссылка_на_картинку'
    const PLAYER_SPRITES = {
        // 'НикИгрока': 'https://ссылка.на/вашу/картинку.png',
        'fireartutzxc': 'data:image/png;base64,',
        'jeriksi': 'data:image/png;base64,',
        'spector99th': 'data:image/png;base64,',
        'tsoivechen210662': 'data:image/png;base64,',
    };

    // 3. Спрайты для НПС (Гром и Кремень)
    const NPC_SPRITES = {
        city: "data:image/png;base64,",
        mine: "data:image/png;base64,"
    };

    // 4. НОВОЕ: Словарь Гильдий
    // Формат: "Название" : { color: "#ЦВЕТ", members: ["Ник1", "Ник2"] }
    const GUILDS = {
        "Дворфийская Гильдия": {
            color: "#ff9900", // Оранжевый
            members: ["jeriksi", "3oda", "enigmo6249", "TsoiVechen210662", "spector99th", "xo.neontop", "timaxionit", "leshalapin", "fireartutzxc", "i_rekd_i", "vordaoluh", "great913", "coda0165_84965", "rav6r", "anantashesha3823", "domino_s67", "hOst1k"]
        },
        "Дискорд канал": {
            color: "#00ffff", // Голубой
            members: ["DFOLtEach", "Oppencrusa"]
        }
    };

    // 5. Выделение игроков в шахте (цвет плашки)
    const HIGHLIGHT_PLAYERS = {
        // "Ник": { color: '#ff0000', bg: 'rgba(255, 0, 0, 0.2)' },
    };

    // 6. Спрайт кирки
    const PICKAXE_SPRITE_URL = "data:image/png;base64,";

    // 7. Настройка положения плашки в шахте
    const NAMEPLATE_CONFIG = {
        offsetX: 0,
        offsetY: -65
    };

    // ==========================================
    // ЧАСТЬ 2: ГЛУШИТЕЛЬ ОШИБОК И БАЗА КЛАССОВ
    // ==========================================
    const IGNORE_STRINGS = ['не запеклось', 'Invalid encoded image data', 'citygl.js'];
    ['log', 'warn', 'error', 'info', 'debug'].forEach(method => {
        const original = console[method];
        console[method] = function(...args) {
            try {
                const str = args.map(arg => (typeof arg === 'string' ? arg : (arg instanceof Error ? arg.message : String(arg)))).join(' ');
                if (IGNORE_STRINGS.some(keyword => str.includes(keyword))) return;
            } catch (e) {}
            original.apply(console, args);
        };
    });

    const CLASSES = {
        legionary:   { key: 'legionary',   name: 'Легионер',   scale: 1, col: 0, row: 0 },
        archer:      { key: 'archer',      name: 'Лучник',     scale: 1, col: 0, row: 0 },
        mage:        { key: 'mage',        name: 'Маг',        scale: 1, col: 0, row: 0 },
        priest:      { key: 'priest',      name: 'Жрец',       scale: 1, col: 0, row: 0 },
        rogue:       { key: 'rogue',       name: 'Разбойник',  scale: 1, col: 0, row: 0 },
        necromancer: { key: 'necromancer', name: 'Некромант',  scale: 1, col: 0, row: 0 },
        paladin:     { key: 'paladin',     name: 'Паладин',    scale: 1, col: 0, row: 0 },
        recruit:     { key: 'recruit',     name: 'Новобранец', scale: 1, col: 0, row: 0 }
    };

    const WEAPON_MAP = {
        necromancer: ['nec_bone_wand', 'nec_old_book', 'nec_skull_staff', 'nec_grimoire', 'nec_crypt_staff', 'nec_black_book', 'orcus_scepter'],
        paladin: ['pal_novice_mace', 'pal_mace', 'pal_war_hammer', 'pal_sun_mace', 'pal_guard_hammer', 'sol_hammer', 'mace', 'flanged_mace', 'smith_hammer', 'warhammer', 'champion_mace'],
        priest: ['censer', 'copper_censer', 'silver_censer', 'gold_censer', 'pontifex_censer', 'vesta_breath'],
        mage: ['staff', 'walking_staff', 'oak_staff', 'ember_staff', 'storm_staff', 'storm_heart', 'crook', 'druid_crook', 'elder_crook'],
        rogue: ['dagger', 'stiletto', 'assassin_dagger', 'rog_shiv', 'rog_dirk', 'rog_kris', 'rog_twin', 'rog_viper', 'mercury_fang'],
        archer: ['bow', 'hunting_bow', 'composite_bow', 'yew_bow', 'longbow', 'sagittarius_bow', 'apollo_bow', 'diana_bow'],
        legionary: ['sword', 'gladius', 'rusty_sword', 'spatha', 'iron_sword', 'sharp_gladius', 'legate_gladius', 'praetorian_spatha', 'aquila_blade', 'hatchet', 'bearded_axe', 'war_axe', 'wood_spear', 'pilum', 'triarius_hasta', 'retiarius_trident', 'wood_club', 'barbarian_club', 'pitchfork']
    };

    const playerGearCache = {};
    let lastMyGear = null;
    let myUsername = 'jeriksi';
    let gearCacheVersion = 0;

    // ==========================================
    // ЧАСТЬ 3: СЕТЬ
    // ==========================================
    function triggerGameRerender() {
        if (window.MDDoodle && typeof window.MDDoodle.update === 'function') window.MDDoodle.update();
        window.dispatchEvent(new Event('resize'));
        processCharacterTab();
    }

    const originalFetch = window.fetch;
    window.fetch = async function(...args) {
        const url = args[0];
        const response = await originalFetch.apply(this, args);
        try {
            if (typeof url === 'string') {
                const clone = response.clone();
                let data = await clone.json();

                if (url.includes('/api/me') && data?.user?.login) {
                    myUsername = data.user.login;
                    if (data?.hero?.gear) {
                        lastMyGear = data.hero.gear;
                        playerGearCache[myUsername] = data.hero.gear;
                    }
                }
                if (url.includes('/api/equip')) {
                    const gear = data?.hero?.gear || data?.gear;
                    if (gear !== undefined) {
                        lastMyGear = gear;
                        playerGearCache[myUsername] = gear;
                        gearCacheVersion++;
                        setTimeout(triggerGameRerender, 50);
                    }
                }
                if (url.includes('/api/city/enter') || url.includes('/api/city/go')) {
                    if (data?.me?.gear) {
                        lastMyGear = data.me.gear;
                        if (myUsername) playerGearCache[myUsername] = data.me.gear;
                    }
                    setTimeout(triggerGameRerender, 50);
                }
                return response;
            }
        } catch (e) {}
        return response;
    };

    function detectPlayerClass(gear, role) {
        if (role && CLASSES[role]) return CLASSES[role];
        if (!gear || !gear.w) return CLASSES.recruit;
        const w = gear.w.toLowerCase();
        for (const [classKey, idList] of Object.entries(WEAPON_MAP)) {
            if (idList.includes(w)) return CLASSES[classKey];
        }
        if (w.includes('nec_') || w.includes('skull') || w.includes('skelet') || w.includes('orcus')) return CLASSES.necromancer;
        if (w.includes('pal_') || w.includes('sol_') || w.includes('hammer') || w.includes('mace')) return CLASSES.paladin;
        if (w.includes('censer') || w.includes('vesta')) return CLASSES.priest;
        if (w.includes('staff') || w.includes('crook') || w.includes('grimoire') || w.includes('book')) return CLASSES.mage;
        if (w.includes('rog_') || w.includes('dagger') || w.includes('fang')) return CLASSES.rogue;
        if (w.includes('bow')) return CLASSES.archer;
        if (w.includes('sword') || w.includes('gladius') || w.includes('axe') || w.includes('spear')) return CLASSES.legionary;
        return CLASSES.recruit;
    }

    // ==========================================
    // ЧАСТЬ 4: ГОРОД (Спрайты + Canvas)
    // ==========================================
    const OriginalBlob = window.Blob;
    window.Blob = new Proxy(OriginalBlob, {
        construct(target, args) {
            const [parts, options] = args;
            if (options && options.type === 'image/svg+xml' && parts && typeof parts[0] === 'string') {
                const svgStr = parts[0];
                if (svgStr.includes('cyq-') && svgStr.length > 18000 && svgStr.length < 30000) {
                    const match = svgStr.match(/<svg([^>]+)>([\s\S]*)<\/svg>/);
                    if (match) {
                        let npcSprite = NPC_SPRITES.city;
                        const newSvg = `<svg ${match[1]} xmlns:xlink="http://www.w3.org/1999/xlink">
                            <g opacity="0">${match[2]}</g>
                            <image href="${npcSprite}" xlink:href="${npcSprite}" x="0" y="0" width="100%" height="100%" style="image-rendering: pixelated;" preserveAspectRatio="none" />
                        </svg>`;
                        return new target([newSvg], options);
                    }
                }
                if (svgStr.includes('<svg') && svgStr.length > 12000 && svgStr.length < 18000) {
                    const match = svgStr.match(/<svg([^>]+)>([\s\S]*)<\/svg>/);
                    if (match) {
                        let spriteUrl = CLASS_SPRITES.legionary;
                        const newSvg = `<svg ${match[1]} xmlns:xlink="http://www.w3.org/1999/xlink">
                            <g opacity="0">${match[2]}</g>
                            <image href="${spriteUrl}" xlink:href="${spriteUrl}" x="0" y="0" width="100%" height="100%" style="image-rendering: pixelated;" preserveAspectRatio="none" />
                        </svg>`;
                        return new target([newSvg], options);
                    }
                }
            }
            return new target(...args);
        }
    });

    // Очистка ников в городе (Canvas)
    const blockMethods = ['fill', 'stroke', 'fillRect', 'strokeRect', 'arc', 'ellipse', 'drawImage'];
    blockMethods.forEach(method => {
        const original = CanvasRenderingContext2D.prototype[method];
        if (!original) return;
        CanvasRenderingContext2D.prototype[method] = function(...args) {
            if (this.canvas && this.canvas.height === 18) return;
            return original.apply(this, args);
        };
    });

    const originalFillText = CanvasRenderingContext2D.prototype.fillText;
    CanvasRenderingContext2D.prototype.fillText = function(text, x, y, maxWidth) {
        if (this.canvas && this.canvas.height === 18) {
            if (/^\d+$/.test(text.trim())) return; // Игнорируем уровень

            let textColor = '#ffffff';
            let shadow = 'none';

            // Ищем цвет гильдии для этого игрока
            let guildColor = null;
            for (const g in GUILDS) {
                if (GUILDS[g].members.includes(text)) {
                    guildColor = GUILDS[g].color;
                    break;
                }
            }

            if (text === myUsername) {
                // Если это ТЫ
                textColor = guildColor ? guildColor : '#ffeb3b'; // Цвет гильдии или желтый
                shadow = textColor;
                this.font = 'bold 14px sans-serif';
                this.shadowBlur = 8;
            } else if (guildColor) {
                // Если это твой согильдиец
                textColor = guildColor;
                shadow = textColor;
                this.shadowBlur = 6;
            } else {
                // Остальные
                this.shadowBlur = 0;
            }

            this.fillStyle = textColor;
            this.shadowColor = shadow;
        }
        return originalFillText.apply(this, arguments);
    };

    // ==========================================
    // ЧАСТЬ 5: UI 2D (Чат)
    // ==========================================
    function initDwarfEngine() {
        if (!window.MDDoodle || typeof window.MDDoodle.jDoodle !== 'function') {
            setTimeout(initDwarfEngine, 300);
            return;
        }
        const originalJDoodle = window.MDDoodle.jDoodle;
        window.MDDoodle.jDoodle = function(seed, mood, uniform, extra, look) {

            if (extra && extra.who && extra.who.startsWith('npc:')) {
                let npcSprite = NPC_SPRITES.mine;
                return `
                    <g transform="translate(60, 170) scale(2.5)">
                        <image href="${npcSprite}" x="-32" y="-64" width="64" height="64" style="image-rendering: pixelated;" preserveAspectRatio="none" />
                    </g>
                `;
            }

            if (document.querySelector('.mn-h')) return originalJDoodle(seed, mood, uniform, extra, look);
            if (!extra || !extra.who) return originalJDoodle(seed, mood, uniform, extra, look);

            let gear = {};
            const isMe = (extra.who === myUsername || extra.who === 'jeriksi');
            if (isMe) gear = lastMyGear || extra.gear || playerGearCache[extra.who] || {};
            else gear = extra.gear || playerGearCache[extra.who] || {};
            if (extra.gear) playerGearCache[extra.who] = extra.gear;

            if (isMe && document.querySelector('#tab-hero.tab.on')) return originalJDoodle(seed, mood, uniform, extra, look);

            const role = extra.role || (look && look.role);
            const playerClass = detectPlayerClass(gear, role);

            let spritesheetUrl = PLAYER_SPRITES[extra.who] || CLASS_SPRITES[playerClass.key] || CLASS_SPRITES.recruit;

            const renderSize = 128;
            const frameSize = 32;
            const posX = playerClass.col * frameSize;
            const posY = playerClass.row * frameSize;
            const offsetX = 62;
            const offsetY = 173;

            return `
                <g class="dwarf-${playerClass.key}" transform="translate(${offsetX}, ${offsetY}) scale(${playerClass.scale})">
                    <image href="${spritesheetUrl}" x="${-renderSize / 2}" y="${-renderSize}" width="${renderSize}" height="${renderSize}" style="image-rendering: pixelated;" preserveAspectRatio="none" clip-path="inset(0px ${frameSize - posX - frameSize}px ${frameSize - posY - frameSize}px ${posX}px)" />
                </g>
            `;
        };
    }
    window.addEventListener('load', initDwarfEngine);

    // ==========================================
    // ЧАСТЬ 6: МЕНЮ ПЕРСОНАЖА
    // ==========================================
    function processCharacterTab() {
        document.querySelectorAll('svg.jl-doodle').forEach(svg => {
            if (svg.dataset.dwarfProcessed === gearCacheVersion.toString()) return;
            let playerClass = CLASSES.recruit;
            if (lastMyGear) playerClass = detectPlayerClass(lastMyGear);

            let spriteUrl = PLAYER_SPRITES[myUsername] || CLASS_SPRITES[playerClass.key] || CLASS_SPRITES.recruit;

            svg.innerHTML = `
                <svg x="-4" y="42" width="128" height="128" viewBox="0 0 32 32">
                    <image href="${spriteUrl}" width="32" height="32" style="image-rendering: pixelated;" preserveAspectRatio="none" />
                </svg>
            `;
            svg.dataset.dwarfProcessed = gearCacheVersion.toString();
        });
    }

    // ==========================================
    // ЧАСТЬ 7: ШАХТА И ПЛАШКИ
    // ==========================================
    const FACING_CONFIG = { invertHorizontal: true, invertVertical: false, forceFlip: false, ignoreGameFlip: false };

    const mineStyleId = 'dwarf-mine-v156-style';
    if (!document.getElementById(mineStyleId)) {
        const style = document.createElement('style');
        style.id = mineStyleId;
        style.innerHTML = `
            @keyframes dwarfWalking { 0%, 100% { transform: translateY(0px) rotate(0deg); } 50% { transform: translateY(-4px) rotate(2deg); } }
            @keyframes dwarfDiggingBody { 0%, 100% { transform: translateY(0px); } 50% { transform: translateY(2px) scaleY(0.97); } }
            @keyframes pickaxeSwing { 0%, 100% { transform: rotate(0deg) translate(0, 0); } 30% { transform: rotate(25deg) translate(0.7px, 0.3px); } 60% { transform: rotate(-40deg) translate(-1px, 0.7px); } 85% { transform: rotate(5deg) translate(-0.3px, 0px); } }
            .dwarf-animated-container { width: 100%; height: 100%; display: flex; align-items: center; justify-content: center; transform: translateY(-60px); position: relative; }
            .dwarf-dir-box { position: relative; width: 80px; height: 80px; display: flex; align-items: center; justify-content: center; }
            .dwarf-flip-wrap { position: relative; width: 80px; height: 80px; display: flex; align-items: center; justify-content: center; transform-origin: center center; transform: scale(var(--flip-x, 1), var(--flip-y, 1)); }
            .dwarf-dir-box.flipped { --flip-x: -1; }
            .dwarf-dir-box.flipped-y { --flip-y: -1; }
            .dwarf-mine-sprite { width: 80px; height: 80px; image-rendering: pixelated; }
            .dwarf-pickaxe { position: absolute; top: 30px; left: 8px; width: 40px; height: 40px; image-rendering: pixelated; transform-origin: bottom center; opacity: 0; pointer-events: none; }
            .dwarf-dir-box.state-walk:not(.state-dig) { animation: dwarfWalking 0.4s infinite ease-in-out; }
            .dwarf-dir-box.state-walk:not(.state-dig) .dwarf-pickaxe { opacity: 0; }
            .dwarf-dir-box.state-dig .dwarf-mine-sprite { animation: dwarfDiggingBody var(--dd, 1.2s) var(--dl, 0s) infinite ease-in-out; }
            .dwarf-dir-box.state-dig .dwarf-pickaxe { opacity: 1; animation: pickaxeSwing var(--dd, 1.2s) var(--dl, 0s) infinite ease-in-out; }

            .dwarf-nameplate {
                position: absolute;
                top: ${NAMEPLATE_CONFIG.offsetY}px;
                left: 50%;
                transform: translateX(calc(-50% + ${NAMEPLATE_CONFIG.offsetX}px));
                font-family: sans-serif; font-size: 14px; font-weight: bold;
                color: #fff; text-shadow: -1px -1px 0 #000, 1px -1px 0 #000, -1px 1px 0 #000, 1px 1px 0 #000;
                white-space: nowrap; pointer-events: none; z-index: 10;
                padding: 2px 6px; border-radius: 4px;
                transition: color 0.2s, text-shadow 0.2s;
            }
            .dwarf-nameplate.is-me {
                font-size: 16px;
                font-weight: 900;
                z-index: 20;
            }
        `;
        document.head.appendChild(style);
    }

    function getMineSpriteForElement(el) {
        try {
            const username = el.getAttribute('data-l') ? el.getAttribute('data-l').trim() : '';
            if (!username) return CLASS_SPRITES.recruit;

            if (PLAYER_SPRITES[username]) return PLAYER_SPRITES[username];

            const lkAttr = el.getAttribute('data-lk') || '';
            let gear = {}, role = null;
            if (lkAttr) {
                try {
                    const lkData = JSON.parse(lkAttr);
                    gear = Array.isArray(lkData) ? lkData[1] : (lkData?.g || lkData?.gear || lkData);
                    role = Array.isArray(lkData) ? lkData[0] : lkData?.role;
                } catch (e) {}
            }

            const lkHasWeapon = gear && gear.w;
            const cacheHasWeapon = playerGearCache[username] && playerGearCache[username].w;
            if (!lkHasWeapon && cacheHasWeapon) gear = playerGearCache[username];

            const playerClass = detectPlayerClass(gear, role);
            return CLASS_SPRITES[playerClass.key] || CLASS_SPRITES.recruit;
        } catch (e) {}
        return CLASS_SPRITES.recruit;
    }

    function initMineHero(el) {
        if (!el.dataset.mineInjected) {
            el.dataset.mineInjected = 'true';
            el.innerHTML = `
                <div class="dwarf-animated-container">
                    <div class="dwarf-nameplate"></div>
                    <div class="dwarf-dir-box">
                        <div class="dwarf-flip-wrap">
                            <img src="" class="dwarf-mine-sprite" />
                            <img src="${PICKAXE_SPRITE_URL}" class="dwarf-pickaxe" />
                        </div>
                    </div>
                </div>
            `;
            el._lastX = null; el._lastY = null; el._lastMovedAt = 0; el._lastDir = null; el._lastSpriteKey = null;
            el._sprite = el.querySelector('.dwarf-mine-sprite');
            el._box = el.querySelector('.dwarf-dir-box');
            el._nameplate = el.querySelector('.dwarf-nameplate');
            new MutationObserver(() => applyHeroState(el)).observe(el, { attributes: true, attributeFilter: ['class'] });
        }
    }

    function applyHeroState(el) {
        const sprite = el._sprite; const box = el._box; const nameplate = el._nameplate;
        if (!sprite || !box) return;

        const username = el.getAttribute('data-l') ? el.getAttribute('data-l').trim() : '';

        document.querySelectorAll('.mn-lbl, .mn-hl, .mn-menm').forEach(lbl => {
            if (lbl.textContent === 'Ты' || lbl.textContent === username) {
                lbl.style.display = 'none';
            }
        });

        if (nameplate) {
            if (username) {
                nameplate.textContent = username;

                nameplate.style.color = '';
                nameplate.style.backgroundColor = '';
                nameplate.style.textShadow = '';
                nameplate.classList.remove('is-me');

                let guildColor = null;
                for (const g in GUILDS) {
                    if (GUILDS[g].members.includes(username)) {
                        guildColor = GUILDS[g].color;
                        break;
                    }
                }

                if (username === myUsername) {
                    nameplate.classList.add('is-me');
                    if (guildColor) {
                        nameplate.style.color = guildColor;
                        nameplate.style.textShadow = `-1px -1px 0 #000, 1px -1px 0 #000, -1px 1px 0 #000, 1px 1px 0 #000, 0 0 10px ${guildColor}, 0 0 20px ${guildColor}`;
                    } else {
                        nameplate.style.color = '#ffeb3b';
                        nameplate.style.textShadow = `-1px -1px 0 #000, 1px -1px 0 #000, -1px 1px 0 #000, 1px 1px 0 #000, 0 0 10px #ffeb3b, 0 0 20px #ffeb3b`;
                    }
                } else if (guildColor) {
                    nameplate.style.color = guildColor;
                    nameplate.style.textShadow = `-1px -1px 0 #000, 1px -1px 0 #000, -1px 1px 0 #000, 1px 1px 0 #000, 0 0 6px ${guildColor}`;
                } else if (HIGHLIGHT_PLAYERS[username]) {
                    nameplate.style.color = HIGHLIGHT_PLAYERS[username].color;
                    nameplate.style.backgroundColor = HIGHLIGHT_PLAYERS[username].bg;
                }
            } else {
                nameplate.textContent = '';
            }
        }

        const gearKey = (el.getAttribute('data-l') || '') + '|' + (el.getAttribute('data-lk') || '') + '|' + gearCacheVersion;
        if (el._lastSpriteKey !== gearKey) {
            el._lastSpriteKey = gearKey;
            const url = getMineSpriteForElement(el);
            if (sprite.getAttribute('src') !== url) sprite.src = url;
        }
        const isDig = el.classList.contains('dig');
        const hasWalk = el.classList.contains('walk');
        const isFl = el.classList.contains('fl');
        const now = performance.now();
        const recentlyMoved = el._lastMovedAt > 0 && (now - el._lastMovedAt) < 180;
        const isWalking = (hasWalk || recentlyMoved) && !isDig;
        box.classList.toggle('state-dig', isDig);
        box.classList.toggle('state-walk', isWalking);
        let wantFlip = (FACING_CONFIG.ignoreGameFlip ? false : isFl) || el._lastDir === 'left';
        if (FACING_CONFIG.invertHorizontal) wantFlip = !wantFlip;
        if (FACING_CONFIG.forceFlip) wantFlip = true;
        box.classList.toggle('flipped', wantFlip);
        box.classList.toggle('flipped-y', FACING_CONFIG.invertVertical);
        if (el._lastDir) box.dataset.dir = el._lastDir;
    }

    function tickHeroes() {
        document.querySelectorAll('.mn-h').forEach(el => {
            if (!el.dataset.mineInjected) initMineHero(el);
            const s = el.getAttribute('style') || '';
            const m = s.match(/translate(?:3d)?\(\s*(-?[\d.]+)px,\s*(-?[\d.]+)px/);
            if (m) {
                const x = parseFloat(m[1]); const y = parseFloat(m[2]);
                if (el._lastX !== null) {
                    const dx = x - el._lastX; const dy = y - el._lastY;
                    if (Math.abs(dx) > 0.4 || Math.abs(dy) > 0.4) {
                        el._lastMovedAt = performance.now();
                        if (Math.abs(dx) > Math.abs(dy)) el._lastDir = dx > 0 ? 'right' : 'left';
                        else el._lastDir = dy > 0 ? 'down' : 'up';
                    }
                }
                el._lastX = x; el._lastY = y;
            }
            applyHeroState(el);
        });

        if (document.querySelector('svg.jl-doodle')) processCharacterTab();
        requestAnimationFrame(tickHeroes);
    }

    const observer = new MutationObserver(mutations => {
        mutations.forEach(m => m.addedNodes.forEach(node => {
            if (node.nodeType !== 1) return;
            if (node.classList?.contains('mn-h')) initMineHero(node);
            node.querySelectorAll?.('.mn-h').forEach(initMineHero);
            if (node.matches?.('svg.jl-doodle') || node.querySelector?.('svg.jl-doodle')) processCharacterTab();
        }));
    });
    observer.observe(document.body, { childList: true, subtree: true });
    document.querySelectorAll('.mn-h').forEach(initMineHero);
    requestAnimationFrame(tickHeroes);

    console.log('%c[DwarfMod v156.0] Абсолютный финал. Город и шахта очищены и покрашены.', 'color:#0f0;font-weight:bold');
})();
